// Pins the vendored copy to @nimiq/core: the fixtures were generated by core
// upstream (auth.fixtures.json, vendored with the code). If a re-copy drifts,
// these fail before any backup does.
import { describe, expect, test } from 'bun:test';
import { blake2b } from './blake2b';
import { addressFromPublicKey, toBytes, verifySignedMessage } from './sign-message';
import { RPC_ENDPOINTS } from './rpc-endpoints';
import FX from './auth.fixtures.json';

const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');

describe('vendored nimiq-settlement v0.9.0', () => {
  test('blake2b matches RFC 7693', () => {
    expect(hex(blake2b(new TextEncoder().encode('abc'), 64)).slice(0, 32)).toBe('ba80a53f981c4d0d6a2797b69f12f6e9');
  });
  test(`${FX.keys.length} public keys derive core's address`, () => {
    for (const k of FX.keys) expect(addressFromPublicKey(toBytes(k.publicKey)!)).toBe(k.address);
  });
  test("a core signature verifies and returns core's address; the UTF-16 length bug does not", async () => {
    const S = FX.sigs;
    expect(await verifySignedMessage({ message: S.message, publicKey: S.publicKey, signature: S.signedMessage, accept: ['signed-message'] })).toEqual({
      ok: true,
      address: S.address,
      prefix: 'signed-message',
    });
    expect((await verifySignedMessage({ message: S.message, publicKey: S.publicKey, signature: S.utf16LengthBug, accept: ['signed-message'] })).ok).toBe(false);
  });
  test('the endpoint list is non-empty https for both networks', () => {
    for (const n of ['main', 'test'] as const) {
      expect(RPC_ENDPOINTS[n].length).toBeGreaterThan(0);
      for (const u of RPC_ENDPOINTS[n]) expect(u.startsWith('https://')).toBe(true);
    }
  });
});
